#!/usr/bin/env python3
"""Compare Ctrl-World predictions against frames generated by LIBERO.

The default path replays an expert LIBERO demo action sequence in the simulator,
uses the first Ctrl-World history window as conditioning, predicts the next
chunk with a trained Ctrl-World checkpoint, and writes GT/PRED/DIFF videos plus
per-frame pixel metrics.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import time
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

os.environ.setdefault("MUJOCO_GL", "osmesa")
os.environ.setdefault("PYOPENGL_PLATFORM", "osmesa")

import h5py
import imageio.v2 as imageio
import numpy as np
import torch
import torch.nn.functional as F
from PIL import Image, ImageDraw
from scipy.spatial.transform import Rotation as R

ACCE_RL_ROOT = Path(__file__).resolve().parents[1]
if str(ACCE_RL_ROOT) not in sys.path:
    sys.path.insert(0, str(ACCE_RL_ROOT))

from libero.libero import benchmark  # noqa: E402

from experiments.robot.libero.libero_utils import (  # noqa: E402
    get_libero_dummy_action,
    get_libero_env,
)
from ctrl_world.config import wm_args  # noqa: E402
from ctrl_world.models.ctrl_world import CrtlWorld  # noqa: E402
from ctrl_world.models.pipeline_ctrl_world import CtrlWorldDiffusionPipeline  # noqa: E402


@dataclass
class EvalSummary:
    benchmark: str
    task_id: int
    task_name: str
    instruction: str
    action_source: str
    demo_hdf5: Optional[str]
    demo_id: str
    checkpoint: str
    output_dir: str
    num_history: int
    num_frames: int
    num_cams: int
    height: int
    width: int
    metrics: Dict[str, Any]
    videos: Dict[str, str]


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Evaluate a trained Ctrl-World checkpoint on LIBERO-generated frames."
    )
    parser.add_argument("--benchmark", type=str, default="libero_spatial")
    parser.add_argument("--task-id", type=int, default=0)
    parser.add_argument("--demo-hdf5", type=str, default=None)
    parser.add_argument("--demo-id", type=str, default="demo_0")
    parser.add_argument(
        "--action-source",
        choices=["demo", "random", "noop"],
        default="demo",
        help="demo replays HDF5 actions in LIBERO; random/noop are smoke-test fallbacks.",
    )
    parser.add_argument(
        "--demo-root",
        type=str,
        default="/mnt/data/lcx3/dataset/libero_spatial",
        help="Directory used to auto-find a task demo HDF5 when --demo-hdf5 is omitted.",
    )
    parser.add_argument(
        "--ckpt-path",
        type=str,
        default="/mnt/data/lcx3/Ctrl-World/model_ckpt/libero_spatial/"
        "2026-07-03T16-55-44_libero_spatial/checkpoint-100000.pt",
    )
    parser.add_argument(
        "--svd-model-path",
        type=str,
        default="/mnt/data/lcx3/checkpoint/ctrl_world/svd/svd_model",
    )
    parser.add_argument(
        "--clip-model-path",
        type=str,
        default="/mnt/data/lcx3/checkpoint/ctrl_world/clip/clip_model",
    )
    parser.add_argument(
        "--stat-path",
        type=str,
        default="/mnt/data/lcx3/dataset/dateset_meta_info/spatial/stat.json",
        help="Ctrl-World action/state normalization stat.json.",
    )
    parser.add_argument("--output-dir", type=str, default="/mnt/data/lcx3/AcceRL/tests_dsj/ctrl_world_libero_eval")
    parser.add_argument("--device", type=str, default="cuda")
    parser.add_argument("--dtype", choices=["bf16", "fp16", "fp32"], default="bf16")
    parser.add_argument("--num-inference-steps", type=int, default=50)
    parser.add_argument("--height", type=int, default=192)
    parser.add_argument("--width", type=int, default=320)
    parser.add_argument("--num-cams", type=int, default=2)
    parser.add_argument("--num-history", type=int, default=6)
    parser.add_argument("--num-frames", type=int, default=5)
    parser.add_argument("--start-index", type=int, default=0)
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--fps", type=int, default=5)
    parser.add_argument(
        "--rotate-libero-images",
        action="store_true",
        help="Rotate LIBERO camera images by 180 degrees. Off by default to match converted Ctrl-World HDF5 data.",
    )
    parser.add_argument(
        "--keep-model-loaded-only",
        action="store_true",
        help="Only load the model and exit after import/model smoke checks.",
    )
    return parser.parse_args()


def torch_dtype(name: str) -> torch.dtype:
    if name == "bf16":
        return torch.bfloat16
    if name == "fp16":
        return torch.float16
    return torch.float32


def normalize_task_text(text: str) -> str:
    keep = []
    for ch in text.lower():
        keep.append(ch if ch.isalnum() else "_")
    out = "".join(keep)
    while "__" in out:
        out = out.replace("__", "_")
    return out.strip("_")


def get_task(benchmark_name: str, task_id: int):
    benchmark_dict = benchmark.get_benchmark_dict()
    if benchmark_name not in benchmark_dict:
        raise ValueError(f"Unknown benchmark {benchmark_name}. Available: {sorted(benchmark_dict)}")
    suite = benchmark_dict[benchmark_name]()
    if task_id < 0 or task_id >= suite.n_tasks:
        raise ValueError(f"task_id {task_id} out of range [0, {suite.n_tasks - 1}]")
    return suite.get_task(task_id), suite


def auto_find_demo_hdf5(demo_root: Path, instruction: str, task_id: int) -> Path:
    files = sorted(demo_root.glob("*_demo.hdf5"))
    if not files:
        raise FileNotFoundError(f"No *_demo.hdf5 files found in {demo_root}")
    normalized_instruction = normalize_task_text(instruction)
    for path in files:
        stem = path.stem
        if stem.endswith("_demo"):
            stem = stem[: -len("_demo")]
        if normalize_task_text(stem) == normalized_instruction:
            return path
    if 0 <= task_id < len(files):
        return files[task_id]
    return files[0]


def load_demo_actions_and_init_state(path: Path, demo_id: str) -> Tuple[np.ndarray, np.ndarray]:
    with h5py.File(path, "r") as f:
        group = f["data"][demo_id]
        actions = np.asarray(group["actions"], dtype=np.float32)
        if "states" in group:
            init_state = np.asarray(group["states"][0])
        elif "init_state" in group.attrs:
            init_state = np.asarray(group.attrs["init_state"])
        else:
            raise KeyError(f"{path}:{demo_id} has neither states dataset nor init_state attr")
    if actions.ndim != 2 or actions.shape[1] != 7:
        raise ValueError(f"Expected demo actions shape [T,7], got {actions.shape}")
    return actions, init_state


def quat_to_axis_angle(quat: np.ndarray) -> np.ndarray:
    quat = np.asarray(quat, dtype=np.float64).copy()
    quat[3] = np.clip(quat[3], -1.0, 1.0)
    return R.from_quat(quat).as_rotvec()


def gripper_scalar(obs: Dict[str, np.ndarray]) -> float:
    qpos = np.asarray(obs["robot0_gripper_qpos"], dtype=np.float64)
    if qpos.ndim == 0:
        return float(qpos)
    return float(qpos.reshape(-1)[-1])


def state7_from_raw_obs(obs: Dict[str, np.ndarray]) -> np.ndarray:
    return np.concatenate(
        [
            np.asarray(obs["robot0_eef_pos"], dtype=np.float64),
            quat_to_axis_angle(np.asarray(obs["robot0_eef_quat"], dtype=np.float64)),
            np.asarray([gripper_scalar(obs)], dtype=np.float64),
        ],
        axis=0,
    ).astype(np.float32)


def camera_frames_from_raw_obs(obs: Dict[str, np.ndarray], rotate: bool) -> List[np.ndarray]:
    frames = [
        np.asarray(obs["agentview_image"], dtype=np.uint8),
        np.asarray(obs["robot0_eye_in_hand_image"], dtype=np.uint8),
    ]
    if rotate:
        frames = [img[::-1, ::-1].copy() for img in frames]
    return frames


def collect_libero_rollout(args: argparse.Namespace, task: Any, instruction: str) -> Tuple[List[List[np.ndarray]], np.ndarray, Optional[Path], str]:
    env, _ = get_libero_env(task, "llava", resolution=256)
    np.random.seed(args.seed)
    actions: Optional[np.ndarray] = None
    init_state: Optional[np.ndarray] = None
    demo_path: Optional[Path] = None

    if args.action_source == "demo":
        demo_path = Path(args.demo_hdf5) if args.demo_hdf5 else auto_find_demo_hdf5(Path(args.demo_root), instruction, args.task_id)
        actions, init_state = load_demo_actions_and_init_state(demo_path, args.demo_id)

    total_needed = args.start_index + args.num_history + args.num_frames
    raw_obs = env.reset()
    if init_state is not None:
        raw_obs = env.set_init_state(init_state)
    for _ in range(10):
        raw_obs, _, _, _ = env.step(get_libero_dummy_action("llava"))

    frames_by_t: List[List[np.ndarray]] = []
    states: List[np.ndarray] = []
    max_action_steps = max(total_needed + 1, total_needed)

    try:
        for t in range(max_action_steps):
            frames_by_t.append(camera_frames_from_raw_obs(raw_obs, rotate=args.rotate_libero_images))
            states.append(state7_from_raw_obs(raw_obs))
            if len(frames_by_t) >= total_needed:
                break

            if args.action_source == "demo":
                assert actions is not None
                action = actions[min(t, len(actions) - 1)]
            elif args.action_source == "random":
                action = np.random.uniform(-1.0, 1.0, size=(7,)).astype(np.float32)
            else:
                action = np.asarray(get_libero_dummy_action("llava"), dtype=np.float32)
            raw_obs, _, done, _ = env.step(action.tolist())
            if done and len(frames_by_t) < total_needed:
                print(f"[warn] LIBERO episode ended early at step {t}; tail frames will repeat.")
                break
    finally:
        env.close()

    while len(frames_by_t) < total_needed:
        frames_by_t.append([img.copy() for img in frames_by_t[-1]])
        states.append(states[-1].copy())

    return frames_by_t, np.stack(states, axis=0).astype(np.float32), demo_path, args.demo_id


def resize_uint8_video(frames: Sequence[np.ndarray], size_hw: Tuple[int, int]) -> np.ndarray:
    x = torch.from_numpy(np.stack(frames, axis=0)).permute(0, 3, 1, 2).float() / 255.0
    x = F.interpolate(x, size=size_hw, mode="bilinear", align_corners=False)
    return (x.clamp(0, 1) * 255).byte().permute(0, 2, 3, 1).cpu().numpy()


def load_ctrl_world_model(args: argparse.Namespace) -> CrtlWorld:
    cfg = wm_args(task_type="replay")
    cfg.svd_model_path = args.svd_model_path
    cfg.clip_model_path = args.clip_model_path
    cfg.ckpt_path = args.ckpt_path
    cfg.val_model_path = args.ckpt_path
    cfg.num_cams = args.num_cams
    cfg.height = args.height
    cfg.width = args.width
    cfg.num_history = args.num_history
    cfg.num_frames = args.num_frames
    cfg.num_inference_steps = args.num_inference_steps
    cfg.dtype = torch_dtype(args.dtype)

    model = CrtlWorld(cfg)
    state = torch.load(args.ckpt_path, map_location="cpu")
    model.load_state_dict(state)
    model.to(args.device).to(cfg.dtype)
    model.eval()
    return model


def normalize_bound(data: np.ndarray, data_min: np.ndarray, data_max: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    out = 2 * (data - data_min) / (data_max - data_min + eps) - 1
    return np.clip(out, -1.0, 1.0).astype(np.float32)


def encode_views_to_stacked_latents(
    model: CrtlWorld,
    frames_by_t: Sequence[List[np.ndarray]],
    height: int,
    width: int,
    dtype: torch.dtype,
    device: str,
) -> torch.Tensor:
    """Return [T, 4, latent_h*num_cams, latent_w]."""
    vae = model.pipeline.vae
    per_cam_latents: List[torch.Tensor] = []
    num_cams = len(frames_by_t[0])
    for cam_id in range(num_cams):
        resized = resize_uint8_video([frames[cam_id] for frames in frames_by_t], (height, width))
        x = torch.from_numpy(resized).permute(0, 3, 1, 2).to(device=device, dtype=dtype)
        x = x / 255.0 * 2.0 - 1.0
        chunks = []
        with torch.no_grad():
            for i in range(0, x.shape[0], 8):
                chunk = x[i : i + 8]
                latent = vae.encode(chunk).latent_dist.sample()
                chunks.append(latent * vae.config.scaling_factor)
        per_cam_latents.append(torch.cat(chunks, dim=0))
    return torch.cat(per_cam_latents, dim=2)


def decode_stacked_latents(
    model: CrtlWorld,
    latents: torch.Tensor,
    num_cams: int,
    height: int,
    width: int,
    chunk_size: int,
) -> List[np.ndarray]:
    """Decode [F,4,latent_h*num_cams,latent_w] into one uint8 video per camera."""
    vae = model.pipeline.vae
    latent_h = height // 8
    videos: List[np.ndarray] = []
    for cam_id in range(num_cams):
        cam_latent = latents[:, :, cam_id * latent_h : (cam_id + 1) * latent_h, :]
        decoded_chunks = []
        with torch.no_grad():
            for i in range(0, cam_latent.shape[0], chunk_size):
                chunk = cam_latent[i : i + chunk_size] / vae.config.scaling_factor
                decoded = vae.decode(chunk, num_frames=chunk.shape[0]).sample
                decoded_chunks.append(decoded)
        video = torch.cat(decoded_chunks, dim=0)
        video = ((video / 2.0 + 0.5).clamp(0, 1) * 255).byte()
        video = video.permute(0, 2, 3, 1).cpu().numpy()
        videos.append(video)
    return videos


def predict_ctrl_world(
    model: CrtlWorld,
    norm_states: np.ndarray,
    stacked_latents: torch.Tensor,
    instruction: str,
    args: argparse.Namespace,
) -> List[np.ndarray]:
    num_history = args.num_history
    num_frames = args.num_frames
    current_idx = args.start_index + num_history
    hist_start = args.start_index
    future_end = current_idx + num_frames

    history = stacked_latents[hist_start:current_idx].unsqueeze(0)
    current_latent = stacked_latents[current_idx : current_idx + 1]
    action_cond = np.concatenate(
        [
            norm_states[hist_start:current_idx],
            norm_states[current_idx:future_end],
        ],
        axis=0,
    )
    expected = num_history + num_frames
    if action_cond.shape != (expected, 7):
        raise ValueError(f"Expected action_cond shape {(expected, 7)}, got {action_cond.shape}")

    act_dtype = model.action_encoder.action_encode[0].weight.dtype
    action_tensor = torch.from_numpy(action_cond).unsqueeze(0).to(device=args.device, dtype=act_dtype)
    with torch.no_grad():
        if model.args.text_cond:
            text_token = model.action_encoder(action_tensor, [instruction], model.tokenizer, model.text_encoder)
        else:
            text_token = model.action_encoder(action_tensor)
        _, pred_latents = CtrlWorldDiffusionPipeline.__call__(
            model.pipeline,
            image=current_latent,
            text=text_token,
            width=args.width,
            height=args.height * args.num_cams,
            num_frames=args.num_frames,
            history=history,
            num_inference_steps=args.num_inference_steps,
            decode_chunk_size=args.num_frames,
            max_guidance_scale=1.0,
            fps=7,
            motion_bucket_id=127,
            output_type="latent",
            return_dict=False,
            frame_level_cond=True,
        )
    return decode_stacked_latents(
        model,
        pred_latents[0],
        num_cams=args.num_cams,
        height=args.height,
        width=args.width,
        chunk_size=args.num_frames,
    )


def compute_metrics(gt_videos: Sequence[np.ndarray], pred_videos: Sequence[np.ndarray]) -> Dict[str, Any]:
    out: Dict[str, Any] = {"per_camera": []}
    all_mse = []
    all_mae = []
    for cam_id, (gt, pred) in enumerate(zip(gt_videos, pred_videos)):
        gt_f = gt.astype(np.float32) / 255.0
        pred_f = pred.astype(np.float32) / 255.0
        err = pred_f - gt_f
        mse_t = np.mean(err * err, axis=(1, 2, 3))
        mae_t = np.mean(np.abs(err), axis=(1, 2, 3))
        psnr_t = -10.0 * np.log10(np.maximum(mse_t, 1e-12))
        all_mse.extend(mse_t.tolist())
        all_mae.extend(mae_t.tolist())
        out["per_camera"].append(
            {
                "camera_id": cam_id,
                "mse_mean": float(np.mean(mse_t)),
                "mae_mean": float(np.mean(mae_t)),
                "psnr_mean": float(np.mean(psnr_t)),
                "mse_per_frame": [float(x) for x in mse_t],
                "mae_per_frame": [float(x) for x in mae_t],
                "psnr_per_frame": [float(x) for x in psnr_t],
            }
        )
    out["overall"] = {
        "mse_mean": float(np.mean(all_mse)),
        "mae_mean": float(np.mean(all_mae)),
        "psnr_mean_from_mean_mse": float(-10.0 * np.log10(max(float(np.mean(all_mse)), 1e-12))),
    }
    return out


def label_image(img: np.ndarray, label: str) -> np.ndarray:
    pil = Image.fromarray(img)
    draw = ImageDraw.Draw(pil)
    draw.rectangle((0, 0, min(img.shape[1], 150), 18), fill=(0, 0, 0))
    draw.text((4, 3), label, fill=(255, 255, 255))
    return np.asarray(pil, dtype=np.uint8)


def make_comparison_video(gt_videos: Sequence[np.ndarray], pred_videos: Sequence[np.ndarray]) -> np.ndarray:
    rows = []
    num_frames = min(v.shape[0] for v in list(gt_videos) + list(pred_videos))
    for t in range(num_frames):
        cam_rows = []
        for cam_id, (gt, pred) in enumerate(zip(gt_videos, pred_videos)):
            diff = np.abs(pred[t].astype(np.int16) - gt[t].astype(np.int16)).astype(np.uint8)
            diff = np.clip(diff * 3, 0, 255).astype(np.uint8)
            row = np.concatenate(
                [
                    label_image(gt[t], f"cam{cam_id} GT"),
                    label_image(pred[t], f"cam{cam_id} PRED"),
                    label_image(diff, f"cam{cam_id} ABS DIFF x3"),
                ],
                axis=1,
            )
            cam_rows.append(row)
        rows.append(np.concatenate(cam_rows, axis=0))
    return np.stack(rows, axis=0)


def write_video(path: Path, frames: np.ndarray, fps: int) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    imageio.mimsave(path, list(frames), fps=fps)


def main() -> None:
    args = parse_args()
    out_dir = Path(args.output_dir) / time.strftime("%Y%m%d_%H%M%S")
    out_dir.mkdir(parents=True, exist_ok=True)

    task, _ = get_task(args.benchmark, args.task_id)
    instruction = task.language
    print(f"[task] {args.benchmark} task_id={args.task_id}: {task.name}")
    print(f"[task] instruction: {instruction}")

    print("[model] loading Ctrl-World...")
    model = load_ctrl_world_model(args)
    print("[model] loaded")
    if args.keep_model_loaded_only:
        return

    print("[libero] collecting real rollout frames...")
    frames_by_t, states, demo_path, demo_id = collect_libero_rollout(args, task, instruction)
    print(f"[libero] collected {len(frames_by_t)} frames, states={states.shape}")
    if demo_path is not None:
        print(f"[libero] replayed demo: {demo_path}:{demo_id}")

    with open(args.stat_path, "r", encoding="utf-8") as f:
        stat = json.load(f)
    state_01 = np.asarray(stat["state_01"], dtype=np.float32)[None, :]
    state_99 = np.asarray(stat["state_99"], dtype=np.float32)[None, :]
    norm_states = normalize_bound(states, state_01, state_99)

    print("[ctrl-world] encoding LIBERO frames and predicting...")
    dtype = torch_dtype(args.dtype)
    stacked_latents = encode_views_to_stacked_latents(
        model,
        frames_by_t,
        height=args.height,
        width=args.width,
        dtype=dtype,
        device=args.device,
    )
    pred_videos = predict_ctrl_world(model, norm_states, stacked_latents, instruction, args)

    current_idx = args.start_index + args.num_history
    gt_frames = frames_by_t[current_idx : current_idx + args.num_frames]
    gt_videos = []
    for cam_id in range(args.num_cams):
        gt_videos.append(resize_uint8_video([frames[cam_id] for frames in gt_frames], (args.height, args.width)))

    metrics = compute_metrics(gt_videos, pred_videos)
    comparison = make_comparison_video(gt_videos, pred_videos)

    video_paths: Dict[str, str] = {}
    comparison_path = out_dir / "comparison_gt_pred_diff.mp4"
    write_video(comparison_path, comparison, fps=args.fps)
    video_paths["comparison"] = str(comparison_path)
    for cam_id, (gt, pred) in enumerate(zip(gt_videos, pred_videos)):
        gt_path = out_dir / f"cam{cam_id}_gt.mp4"
        pred_path = out_dir / f"cam{cam_id}_pred.mp4"
        write_video(gt_path, gt, fps=args.fps)
        write_video(pred_path, pred, fps=args.fps)
        video_paths[f"cam{cam_id}_gt"] = str(gt_path)
        video_paths[f"cam{cam_id}_pred"] = str(pred_path)

    summary = EvalSummary(
        benchmark=args.benchmark,
        task_id=args.task_id,
        task_name=task.name,
        instruction=instruction,
        action_source=args.action_source,
        demo_hdf5=str(demo_path) if demo_path is not None else None,
        demo_id=demo_id,
        checkpoint=args.ckpt_path,
        output_dir=str(out_dir),
        num_history=args.num_history,
        num_frames=args.num_frames,
        num_cams=args.num_cams,
        height=args.height,
        width=args.width,
        metrics=metrics,
        videos=video_paths,
    )
    summary_path = out_dir / "summary.json"
    summary_path.write_text(json.dumps(asdict(summary), indent=2), encoding="utf-8")

    print("[done] wrote:")
    print(f"  summary: {summary_path}")
    for key, value in video_paths.items():
        print(f"  {key}: {value}")
    print("[metrics]", json.dumps(metrics["overall"], indent=2))


if __name__ == "__main__":
    main()
